-- Fast Ingestion Script for CleanTech Open 363-Column Data
SET search_path TO cleantech, public;

\echo 'Loading rubric_catalog (363 questions)...'
\copy cleantech.rubric_catalog (question_id, orig_q_id, cat_code, category_name, data_type, verification_role, question_text, weight) FROM 'rubric_catalog.csv' WITH (FORMAT csv, HEADER true, NULL '');

\echo 'Loading startups (954 records)...'
\copy cleantech.startups (startup_id, company_name, cohort_year, founder, raw_data_dir, evaluation_status) FROM 'startups.csv' WITH (FORMAT csv, HEADER true, NULL '');

